from pathlib import Path
import json,subprocess,hashlib
p=Path('g2/analysis/xuantie-csky-dsp-execution-20261009T201800Z');old=json.loads((p/'harness-build-results.json').read_text());cmd=next(x['command'] for x in old if '/out/harness.c' in x['command']).copy();cmd.insert(cmd.index('-c'),'-DABS_ORACLE_ONLY=1');q=subprocess.run(cmd,capture_output=True,text=True);assert q.returncode==0,q.stderr;link=old[-1]['command'].copy();link[link.index('/out/harness.elf')]='/out/abs-oracle.elf';z=subprocess.run(link,capture_output=True,text=True);assert z.returncode==0,z.stderr;(p/'abs-oracle-build-results.json').write_text(json.dumps({'compile_command':cmd,'compile_stderr':q.stderr,'link_command':link,'link_stderr':z.stderr,'sha256':hashlib.sha256((p/'abs-oracle.elf').read_bytes()).hexdigest()},indent=2)+'\n');print('ABS oracle linked')
